fn main(){
    // ---- 1. inclusion-exclusion on axis-aligned rects (exact integers) ----
    let r=[[0i64,0,50,50],[25,25,75,75],[50,50,100,100]];
    let ar=|b:[i64;4]| { let w=(b[2]-b[0]).max(0); let h=(b[3]-b[1]).max(0); w*h };
    let inter=|a:[i64;4],b:[i64;4]|->[i64;4]{[a[0].max(b[0]),a[1].max(b[1]),a[2].min(b[2]),a[3].min(b[3])]};
    let mut tot=0i64;
    for i in 0..3 { tot+=ar(r[i]); }
    for i in 0..3 { for j in i+1..3 { tot-=ar(inter(r[i],r[j])); } }
    tot+=ar(inter(inter(r[0],r[1]),r[2]));
    println!("inclusion-exclusion union area = {}", tot);

    // ---- 2. brute-force half-integer cell count (each cell 0.5x0.5 = 0.25 area) ----
    let mut cells=0i64;
    for xi in 0..200 { for yi in 0..200 {
        let x=xi as f64*0.5+0.25; let y=yi as f64*0.5+0.25;
        let inside=r.iter().any(|b| x>b[0] as f64 && x<b[2] as f64 && y>b[1] as f64 && y<b[3] as f64);
        if inside {cells+=1;}
    }}
    println!("brute-force area = {}", cells as f64*0.25);

    // ---- 3. shoelace of the claimed 12-vertex ring, Clipper2 term order ----
    let p:[[i64;2];12]=[[0,0],[50,0],[50,25],[75,25],[75,50],[100,50],[100,100],[50,100],[50,75],[25,75],[25,50],[0,50]];
    let n=p.len();
    let mut a=0.0f64; // start with closing edge (last,first) then (0,1)...
    let mut prev=p[n-1];
    for i in 0..n { let c=p[i]; a += ((prev[1]+c[1]) as f64)*((prev[0]-c[0]) as f64); prev=c; }
    println!("shoelace signedArea = {}", 0.5*a);
    println!("printf %g of that   = {:.4}", 0.5*a);

    // ---- 4. winding numbers of the 4 quadrant faces at (50,50), NonZero ----
    // ring winding via crossing-number with sign, each rect given as CCW
    let rings:Vec<Vec<[i64;2]>> = r.iter().map(|b| vec![[b[0],b[1]],[b[2],b[1]],[b[2],b[3]],[b[0],b[3]]]).collect();
    let wind=|px:f64,py:f64,ring:&Vec<[i64;2]>|->i32{
        let mut w=0; let n=ring.len();
        for i in 0..n { let a=ring[i]; let b=ring[(i+1)%n];
            let (ax,ay,bx,by)=(a[0] as f64,a[1] as f64,b[0] as f64,b[1] as f64);
            if ay<=py { if by>py { let cr=(bx-ax)*(py-ay)-(px-ax)*(by-ay); if cr>0.0 {w+=1;} } }
            else if by<=py { let cr=(bx-ax)*(py-ay)-(px-ax)*(by-ay); if cr<0.0 {w-=1;} }
        } w };
    for (nm,px,py) in [("SW(49.5,49.5)",49.5,49.5),("SE(50.5,49.5)",50.5,49.5),("NE(50.5,50.5)",50.5,50.5),("NW(49.5,50.5)",49.5,50.5)] {
        let w:i32=rings.iter().map(|rg| wind(px,py,rg)).sum();
        println!("  {} w={} nonzero_inside={}", nm, w, w!=0);
    }

    // ---- 5. do any two edges overlap COLLINEARLY with positive length? ----
    let mut segs:Vec<(usize,[i64;2],[i64;2])>=vec![];
    for (k,rg) in rings.iter().enumerate(){ let n=rg.len(); for i in 0..n {segs.push((k,rg[i],rg[(i+1)%n]));}}
    for i in 0..segs.len(){ for j in i+1..segs.len(){
        let (ka,a1,a2)=segs[i]; let (kb,b1,b2)=segs[j]; if ka==kb {continue;}
        let d1=[a2[0]-a1[0],a2[1]-a1[1]]; let d2=[b2[0]-b1[0],b2[1]-b1[1]];
        if d1[0]*d2[1]-d1[1]*d2[0]!=0 {continue;}                     // not parallel
        let e=[b1[0]-a1[0],b1[1]-a1[1]];
        if d1[0]*e[1]-d1[1]*e[0]!=0 {continue;}                       // not collinear
        // project onto d1
        let t=|p:[i64;2]| (p[0]-a1[0])*d1[0]+(p[1]-a1[1])*d1[1];
        let (lo,hi)=(0i64.min(t(a2)),0i64.max(t(a2)));
        let (blo,bhi)=(t(b1).min(t(b2)),t(b1).max(t(b2)));
        let (olo,ohi)=(lo.max(blo),hi.min(bhi));
        if ohi>olo { println!("COLLINEAR OVERLAP len>0 between r{}{:?}-{:?} and r{}{:?}-{:?}",ka,a1,a2,kb,b1,b2); }
        else if ohi==olo { println!("collinear TOUCH (zero length) r{} {:?}-{:?} / r{} {:?}-{:?}",ka,a1,a2,kb,b1,b2); }
    }}

    // ---- 6. enumerate all proper edge-edge crossings ----
    println!("-- crossings --");
    for i in 0..segs.len(){ for j in i+1..segs.len(){
        let (ka,a1,a2)=segs[i]; let (kb,b1,b2)=segs[j]; if ka==kb {continue;}
        let d1=[a2[0]-a1[0],a2[1]-a1[1]]; let d2=[b2[0]-b1[0],b2[1]-b1[1]];
        let den=d1[0]*d2[1]-d1[1]*d2[0]; if den==0 {continue;}
        let e=[b1[0]-a1[0],b1[1]-a1[1]];
        let tn=e[0]*d2[1]-e[1]*d2[0]; let un=e[0]*d1[1]-e[1]*d1[0];
        let (tn,un,den)= if den<0 {(-tn,-un,-den)} else {(tn,un,den)};
        if tn<0||tn>den||un<0||un>den {continue;}
        let x=a1[0] as f64 + (tn as f64/den as f64)*d1[0] as f64;
        let y=a1[1] as f64 + (tn as f64/den as f64)*d1[1] as f64;
        let endp = tn==0||tn==den||un==0||un==den;
        println!("  ({},{}) r{}x r{} {}", x,y,ka,kb, if endp {"ENDPOINT/touch"} else {"proper X"});
    }}
}
